export default function BangladeshMap({
  width = 400,
  height = 500,
  selectedDistricts = [],
  onDistrictPress,
  fillColor = '#D8D8D8',
  selectedColor = '#2E7D32',
  strokeColor = '#FFFFFF',
  strokeWidth = 0.6,
}: BangladeshMapProps) {
  return (
    <View style={styles.container}>
      <Svg width={width} height={height} viewBox="0 0 400 500">
        <G>
          {DISTRICT_PATHS.map(district => {
            const isSelected = selectedDistricts.includes(district.name);
            return (
              <Path
                key={district.name}
                d={district.d}
                fill={isSelected ? selectedColor : fillColor}
                stroke={strokeColor}
                strokeWidth={strokeWidth}
                onPress={() => onDistrictPress && onDistrictPress(district.name)}
              />
            );
          })}
        </G>
      </Svg>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    justifyContent: 'center',
  },
});
